755	func sortEnvelope(env *envelope) {
756		sort.Slice(env.Circuits, func(i, j int) bool {
757			if env.Circuits[i].Name != env.Circuits[j].Name {
758				return env.Circuits[i].Name < env.Circuits[j].Name
759			}
760			return env.Circuits[i].Version < env.Circuits[j].Version
761		})
762		sort.Slice(env.Setups, func(i, j int) bool {
763			if env.Setups[i].Name != env.Setups[j].Name {
764				return env.Setups[i].Name < env.Setups[j].Name
765			}
766			return env.Setups[i].Version < env.Setups[j].Version
767		})
768		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
769		sort.Slice(env.Artifacts, func(i, j int) bool {
770			if env.Artifacts[i].Name != env.Artifacts[j].Name {
771				return env.Artifacts[i].Name < env.Artifacts[j].Name
772			}
773			return env.Artifacts[i].Version < env.Artifacts[j].Version
774		})
775	}
776	
777	// validateEnvelope re-checks every invariant on load so a tampered or
778	// hand-edited file cannot bypass the domain rules.
779	func validateEnvelope(env envelope) error {
780		seenCircuit := make(map[[2]string]bool)
781		circuitOK := make(map[[2]string]bool)
782		for i, c := range env.Circuits {
783			key := [2]string{c.Name, itoa(c.Version)}
784			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
785				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
786			}
787			if c.Version <= 0 {
788				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
789			}
790			if seenCircuit[key] {
791				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
792			}
793			seenCircuit[key] = true
794			if c.Constraints <= 0 {
795				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
796			}
797			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
798				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
799			}
800			if c.Definition != nil {
801				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
802					return err
803				}
804			}
805			circuitOK[key] = true
806		}
807		seenSetup := make(map[[2]string]bool)
808		for i, p := range env.Setups {
809			key := [2]string{p.Name, itoa(p.Version)}
810			if !circuitOK[key] {
811				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
812			}
813			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
814			if c == nil || !c.Frozen {
815				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
816			}
817			if seenSetup[key] {
818				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
819			}
820			seenSetup[key] = true
821		}
822		seenJob := make(map[string]bool)
823		for i, j := range env.Jobs {
824			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
825				return fmt.Errorf("job #%d has an empty or blank id", i+1)
826			}
827			if seenJob[j.ID] {
828				return fmt.Errorf("job %q appears more than once", j.ID)
829			}
830			seenJob[j.ID] = true
831			if j.Kind != "prove" {
832				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
833			}
834			if j.Attempt <= 0 {
835				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
836			}
837			key := [2]string{j.Circuit, itoa(j.Version)}
838			if !circuitOK[key] {
839				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
840			}
841			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
842			if c == nil || !c.Frozen {
843				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
844			}
845			if !seenSetup[key] {
846				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
847			}
848			// A recorded compiled-artifact binding must still resolve against the
849			// pinned version's artifact; a dangling or mismatched binding makes
850			// the file unreadable rather than silently dropping the binding.
851			if j.CompiledHash != "" {
852				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
853				if artifact == nil {
854					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
855				}
856				if artifact.Hash != j.CompiledHash {
857					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
858						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
859				}
860			}
861		}
862		seenArtifact := make(map[[2]string]bool)
863		for i, a := range env.Artifacts {
864			key := [2]string{a.Name, itoa(a.Version)}
865			if !circuitOK[key] {
866				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
867			}
868			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
869			if c == nil || !c.Frozen {
870				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
871			}
872			if seenArtifact[key] {
873				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
874			}
875			seenArtifact[key] = true
876			if c.Definition == nil {
877				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
878			}
879			if a.Constraints != c.Constraints {
880				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
881					a.Name, a.Version, a.Constraints, c.Constraints)
882			}
883			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
884			if err != nil {
885				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
886			}
887			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
888				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
889			}
890			wantHash := artifactHash(a.Name, a.Version, def)
891			if a.Hash != wantHash {
892				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
893					a.Name, a.Version, a.Hash, wantHash)
894			}
895		}
896		return nil
897	}
898	
899	// validatePersistDefinition re-validates a stored definition against its
900	// version's declared counts: prime modulus, in-range wires and an exact
901	// constraint count match.
902	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
903		parsed, err := definitionFromPersist(*def, public, private)
904		if err != nil {
905			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
906		}
907		if !parsed.compatibleWith(constraints, public, private) {
908			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
909		}
910		return nil
911	}
912	
913	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
914		for i := range cs {
915			if cs[i].Name == name && cs[i].Version == version {
916				return &cs[i]
917			}
918		}
919		return nil
920	}
921	
922	func itoa(v int) string { return fmt.Sprintf("%d", v) }
923

