161	// out-of-range modulus, malformed coefficients, wire indexes outside
162	// [0, 1+public+private) and a constraint count that does not equal the
163	// circuit version's declared count. The wire layout is wire 0 = constant 1,
164	// followed by the declared public inputs and then the private inputs.
165	func parseDefinitionJSON(raw []byte, public, private, wantCount int) (*canonicalDefinition, error) {
166		shape, err := decodeDefinitionShape(raw, importDefinitionSource)
167		if err != nil {
168			return nil, err
169		}
170		return shape.canonicalize(public, private, wantCount)
171	}
