173	// canonicalize applies the domain rules to a structurally decoded
174	// definition and returns the canonical form: terms merged per wire,
175	// coefficients reduced modulo p, zeros dropped, wires sorted ascending
176	// within each linear combination. The modulus must be a prime in
177	// [2, maxModulus], the constraint count must equal the version's declared
178	// count, every coefficient must be a signed decimal integer and every wire
179	// must lie inside the declared public/private input layout. Both definition
180	// sources run through this same pipeline: the importer on the user's JSON
181	// document, the store on the shape re-decoded from committed data.
182	func (s definitionShape) canonicalize(public, private, wantCount int) (*canonicalDefinition, error) {
183		p, err := parseModulus(s.modulus)
