50		if err != nil {
51			t.Fatal(err)
52		}
53		var wire struct {
54			Circuits []json.RawMessage `json:"circuits"`
55		}
56		if err := json.Unmarshal(raw, &wire); err != nil {
57			t.Fatal(err)
58		}
59		rec := []byte(wire.Circuits[0])
60		var compact bytes.Buffer
61		if err := json.Compact(&compact, rec); err != nil {
62			t.Fatal(err)
63		}
64		key := `"` + field + `"`
65		if escaped {
66			key = "\"\\u" + toHex(field[0]) + field[1:] + "\""
67		}
